const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)
const transaction_row = require('transaction_row')

module.exports = transaction_history

async function transaction_history(opts = {}, { onClose, onRowClick } = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb
  const on = { style: inject, data: ondata }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="transaction-history">
      <div class="transaction-history-header">
        <span>Transaction History</span>
        <button class="history-close">✕</button>
      </div>
      <div class="transaction-history-body"></div>
    </div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const body = shadow.querySelector('.transaction-history-body')
  const closeBtn = shadow.querySelector('.history-close')

  const subs = await sdb.watch(onbatch)

  // hide overlay on close
  closeBtn.addEventListener('click', () => {
    if (onClose) onClose()
  })
  // ---
  // Expose _update 
  el._update = function (txArray) {
    renderAll(txArray)
  }

  // Initial render from fallback subs (static data while waiting for live data)
  const fallbackTxs = subs.slice(1).map(sub => ({
    tid: sub.tid || sub.id || 'Unknown',
    ttime: sub.ttime || '',
    tamount: sub.tamount || '0',
    dateString: sub.dateString || '',
    avatar: sub.avatar || '',
    txid: sub.txid || ''
  }))
  if (fallbackTxs.length > 0) renderAll(fallbackTxs)

  return el

  // ---- Render all transactions grouped by date ----
  function renderAll(txArray) {
    body.innerHTML = ''
    if (!Array.isArray(txArray) || txArray.length === 0) {
      body.innerHTML = '<div style="text-align:center; color:gray; padding:40px; font-size:14px;">No transactions yet</div>'
      return
    }

    // Group by dateString
    const groups = {}
    for (const tx of txArray) {
      const key = tx.dateString || 'Unknown'
      if (!groups[key]) groups[key] = []
      groups[key].push(tx)
    }

    // Sort date keys newest-first
    const sortedDates = Object.keys(groups).sort((a, b) => {
      if (a === 'Unknown') return 1
      if (b === 'Unknown') return -1
      return new Date(b) - new Date(a)
    })

    for (const date of sortedDates) {
      const dateLabel = _getDateLabel(date)
      const dateEl = document.createElement('div')
      dateEl.className = 'transaction-date'
      dateEl.textContent = dateLabel || date
      body.appendChild(dateEl)

      for (const tx of groups[date]) {
        const rowEl = _makeRow(tx)
        body.appendChild(rowEl)
      }
    }
  }

  function _makeRow(tx) {
    const rowEl = document.createElement('div')
    const rowShadow = rowEl.attachShadow({ mode: 'closed' })
    let avatar = tx.avatar || ''
    const isRandom = !avatar && _isRandomString(tx.tid)
    if (!avatar) avatar = isRandom
      ? `https://api.dicebear.com/7.x/identicon/svg?seed=${encodeURIComponent(tx.tid)}`
      : 'https://cdn-icons-png.flaticon.com/512/847/847969.png'
    const displayTid = _shortenTid(tx.tid || 'Unknown')
    rowShadow.innerHTML = `
      <div class="transaction-row">
        <div class="transaction-detail">
          <div class="transaction-avatar"><img src="${avatar}" alt="avatar" /></div>
          <div class="transaction-data">
            <div class="transaction-id">${displayTid}</div>
            <div class="transaction-time">${tx.ttime || '\u2014'}</div>
          </div>
        </div>
        <div class="transaction-amount"><span>${tx.tamount || '0'} &#x20BF;</span></div>
      </div>
      <style>
        .transaction-row { display: flex; flex-direction: row; align-items: center; justify-content: space-between; margin-top: 12px; font-size: 14px; padding: 8px 4px; border-radius: 8px; transition: background-color 0.3s; }
        .transaction-row:hover { background-color: #f0f0f0; cursor: pointer; }
        .transaction-detail { display: flex; flex-direction: row; align-items: center; gap: 10px; }
        .transaction-avatar img { width: 40px; height: 40px; border-radius: 50%; }
        .transaction-data { display: flex; flex-direction: column; text-align: start; }
        .transaction-id { font-size: 16px; font-weight: 500; }
        .transaction-time { color: gray; font-size: 13px; }
        .transaction-amount { font-size: 18px; font-weight: 500; }
      </style>
    `
    rowEl.addEventListener('click', function () {
      if (onRowClick) onRowClick(tx)
    })
    return rowEl
  }

  // ---- Helpers ----
  function _getDateLabel(dateString) {
    if (!dateString || dateString === 'Unknown') return dateString
    const today = new Date()
    const target = new Date(dateString)
    const diffInDays = Math.floor(
      (today.setHours(0, 0, 0, 0) - target.setHours(0, 0, 0, 0)) / (1000 * 60 * 60 * 24)
    )
    if (diffInDays === 0) return 'Today'
    if (diffInDays === 1) return 'Yesterday'
    return target.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })
  }

  function _shortenTid(tid) {
    if (tid.length > 14) return tid.slice(0, 8) + '...' + tid.slice(-4)
    return tid
  }

  function _isRandomString(str) {
    if (!str) return true
    if (/[0-9@#$_-]/.test(str)) return true
    if (str.length > 12 && !/\s/.test(str)) return true
    const upper = (str.match(/[A-Z]/g) || []).length
    const lower = (str.match(/[a-z]/g) || []).length
    if ((upper > 4 && lower > 4) && !/\s/.test(str)) return true
    return false
  }
  //  ---
  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(p => drive.get(p).then(f => f.raw))
      )
      const fn = on[type] || fail
      await fn(data)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  function ondata() { }
}

function fallback_module() {
  return {
    api,
    _: {
      'transaction_row': {
        $: ''
      }
    }
  }
  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    const transaction_row = {
      mapping: {
        style: 'style',
        data: 'data'
      }
    }
    opts.value.forEach((transaction, index) => {
      transaction_row[index] = transaction
    })
    return {
      drive: {
        'style/': {
          'transaction_history.css': {
            '$ref': 'transaction_history.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      },
      _: {
        transaction_row
      }
    }
  }
}

